import {getLocale,getNumberLocale,translate} from './i18n.mjs';
import {evaluateDelivery,buildDeliverySeries,restoreDelivery,FOLLOWUP_VERSION} from './followup-engine.mjs';
const B=(en,tr)=>({en,tr}),L=v=>typeof v==='object'&&v?v[getLocale()]:v;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=1)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString(getNumberLocale(),{maximumFractionDigits:d}):'—';
const blank=()=>({episodeId:'',periodStart:'',periodEnd:'',actualEnergy:null,actualProtein:null,targetVersion:'',source:'',targetsStable:false,confirmed:false,invalidFields:[]});
const fieldLabels={episodeId:B('Admission / episode code','Yatış / dönem kodu'),periodStart:B('Actual-intake window · start','Gerçek alım dönemi · başlangıç'),periodEnd:B('Actual-intake window · end','Gerçek alım dönemi · bitiş'),actualEnergy:B('Actual total energy · all sources','Gerçek toplam enerji · tüm kaynaklar'),actualProtein:B('Actual total protein · all sources','Gerçek toplam protein · tüm kaynaklar'),targetVersion:B('Physician plan ID / version','Hekim planı kimliği / sürümü'),source:B('Intake chart / source version','Alım çizelgesi / kaynak sürümü')};
const contexts={icu:B('ICU','YBÜ'),ward:B('Ward','Servis')},phases={early:B('Early acute','Erken akut'),late:B('Late acute','Geç akut'),recovery:B('Recovery','İyileşme')};
const DAY=86400000;
export function initFollowup({getInput,getClinicalMeasures,getVisits,getSource,getResult,getImportedComparisons,onDraftChange,onSave,onExamples,navigate,toast}){
 const $=id=>document.getElementById(id);let measures=blank(),language='',excludedIds=new Set();
 function fields(){
  const control=(key,type='text',unit='')=>`<div class="field"><label for="delivery-${key}">${L(fieldLabels[key])}</label><div class="input-wrap"><input id="delivery-${key}" data-delivery-field="${key}" type="${type}" value="${esc(measures[key]??'')}" ${type==='number'?`min="0" max="${key==='actualEnergy'?15000:500}" step="any" inputmode="decimal"`:`maxlength="${key==='episodeId'?80:160}"`} ${key.startsWith('period')?'placeholder="2026-10-24T08:00+03:00"':''} autocomplete="off">${unit?`<span class="unit">${unit}</span>`:''}</div></div>`;
  $('deliveryForm').innerHTML=`<div class="delivery-heading"><span class="eyebrow">${L(B('FROM PRESCRIPTION TO DELIVERY','PLANDAN GERÇEK ALIMA'))}</span><h2>${L(B('Record what the patient actually received.','Hastanın gerçekten aldığı miktarı kaydedin.'))}</h2><p>${L(B('Use one complete 24-hour window. Planned formula volume is not actual intake; administered intake does not prove absorption.','Tek ve tam 24 saatlik dönem kullanın. Planlanan mama hacmi gerçek alım değildir; verilen miktar emilimi kanıtlamaz.'))}</p></div><div id="deliveryTargets" class="delivery-targets"></div><div class="fields">${control('episodeId')}${control('targetVersion')}${control('periodStart')}${control('periodEnd')}${control('actualEnergy','number','kcal / 24h')}${control('actualProtein','number','g / 24h')}${control('source')}</div><button type="button" id="deliveryWindow" class="text-button">${L(B('Fill a local 08:00 → 08:00 window ending on the assessment date','Değerlendirme tarihinde biten yerel 08:00 → 08:00 dönemini doldur'))}</button><p class="footnote">${L(B('Times accept ISO 8601 with explicit offsets. Without offsets they are local wall times, not verified elapsed time; reconcile daylight-saving or clock changes. Verify the window against the source.','Zamanlar açık UTC ofsetli ISO 8601 kabul eder. Ofsetsiz zamanlar yerel saatlerdir; doğrulanmış geçen süre değildir. Yaz saati/saat değişimini ve kaynak dönemini kontrol edin.'))}</p><p class="footnote">${L(B('Total oral + enteral + parenteral intake, modular protein and non-nutritional calories (e.g. IV dextrose or lipid sedation). Count each source once. Do not enter the planned volume as delivered intake.','Toplam oral + enteral + parenteral alım, protein modülleri ve beslenme dışı kaloriler (örn. IV dekstroz veya lipitli sedasyon). Her kaynağı bir kez sayın. Planlanan hacmi verilen alım gibi girmeyin.'))}</p><label class="check-field"><input id="delivery-targetsStable" type="checkbox" ${measures.targetsStable?'checked':''}><span>${L(B('The displayed physician targets applied unchanged throughout this exact 24-hour window.','Görüntülenen hekim hedefleri bu tam 24 saat boyunca değişmeden geçerliydi.'))}</span></label><label class="check-field"><input id="delivery-confirmed" type="checkbox" ${measures.confirmed?'checked':''}><span>${L(B('I verified the complete actual intake, period, source and absence of double counting.','Tam gerçek alımı, dönemi, kaynağı ve çift sayım olmadığını doğruladım.'))}</span></label><div class="button-row"><button type="button" id="deliverySave" class="button primary">${L(B('Save assessment with this intake record','Bu alım kaydıyla değerlendirmeyi kaydet'))}</button><button type="button" id="deliveryHistory" class="button secondary">${L(B('View follow-up','İzlemi görüntüle'))} →</button></div><p id="deliveryStatus" role="status"></p>`;
  for(const el of document.querySelectorAll('[data-delivery-field]'))el.addEventListener('input',()=>{const key=el.dataset.deliveryField;measures[key]=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;measures.invalidFields=measures.invalidFields.filter(v=>v!==key);if(!el.validity.valid)measures.invalidFields.push(key);measures.confirmed=false;measures.targetsStable=false;$('delivery-confirmed').checked=false;$('delivery-targetsStable').checked=false;onDraftChange?.();refresh();});
  for(const key of ['confirmed','targetsStable'])$('delivery-'+key).addEventListener('change',event=>{measures[key]=event.target.checked;onDraftChange?.();refresh();});
  $('deliveryWindow').addEventListener('click',()=>{const date=getInput().visitDate;if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))return;const before=new Date(date+'T12:00:00Z');before.setUTCDate(before.getUTCDate()-1);measures.periodStart=before.toISOString().slice(0,10)+'T08:00';measures.periodEnd=date+'T08:00';measures.confirmed=false;measures.targetsStable=false;measures.invalidFields=measures.invalidFields.filter(k=>!k.startsWith('period'));language='';onDraftChange?.();refresh();});
  $('deliverySave').addEventListener('click',()=>{const evaluated=evaluateDelivery(getInput(),measures,getClinicalMeasures?.());if(!evaluated.valid){$('deliveryStatus').textContent=L(B('Complete and verify the intake record before saving it. Other assessment records can still be saved in Research records.','Alım kaydını kaydetmeden önce tamamlayıp doğrulayın. Diğer değerlendirmeler Araştırma kayıtlarından kaydedilebilir.'));return;}if(onSave()!==true){$('deliveryStatus').textContent=L(B('The intake record was not saved. Check the study ID, date and session capacity.','Alım kaydı kaydedilmedi. Çalışma kodunu, tarihi ve oturum kapasitesini kontrol edin.'));return;}$('deliveryStatus').textContent=L(B('Assessment and intake record saved in this session. Export before refreshing.','Değerlendirme ve alım kaydı bu oturumda saklandı. Yenilemeden önce dışa aktarın.'));});
  $('deliveryHistory').addEventListener('click',()=>navigate('research'));
  language=getLocale();
 }
 function scope(){const input=getInput();return {studyId:input.studyId,episodeId:measures.episodeId,context:input.context,phase:input.phase,targetVersion:measures.targetVersion};}
 function signature(){const s=scope();return [s.studyId,s.episodeId,L(contexts[s.context]),L(phases[s.phase]),s.targetVersion].map(v=>esc(v||'—')).join(' · ');}
 function sourceLinks(ids){return `<details><summary>${L(B('Original guidance & methods','Özgün rehberler ve yöntem'))}</summary><ul>${ids.map(id=>{const source=getSource(id);return source?`<li><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(translate(source.title))} ↗</a> · ${esc(translate(source.access))}</li>`:'';}).join('')}</ul></details>`;}
 function ratioCard(label,value,actual,target,unit,tone){return `<article class="delivery-kpi ${tone}"><span>${L(label)}</span><strong>${num(value)}<small>%</small></strong><p>${num(actual)} / ${num(target)} ${unit}</p></article>`;}
 function chart(rows,kind='delivery'){
  const usable=kind==='nitrogen'?rows.filter(r=>typeof r.nitrogen==='number'):rows;if(!usable.length)return '';
  const width=720,height=230,left=45,right=20,top=25,bottom=45;
  const start=rows[0].period.startMs,end=rows.at(-1).period.startMs;
  const values=kind==='nitrogen'?usable.map(r=>r.nitrogen):rows.flatMap(r=>[r.percent.energy,r.percent.protein]);
  const min=kind==='nitrogen'?Math.min(-1,Math.floor(Math.min(...values)/5)*5):0;
  const max=kind==='nitrogen'?Math.max(1,Math.ceil(Math.max(...values)/5)*5):Math.max(100,Math.ceil(Math.max(...values)/25)*25);
  const x=r=>start===end?width/2:left+(r.period.startMs-start)/(end-start)*(width-left-right),y=value=>height-bottom-(value-min)/(max-min)*(height-top-bottom);
  const series=kind==='nitrogen'?[{key:'nitrogen',label:B('Estimated nitrogen balance','Yaklaşık azot dengesi'),tone:'nitrogen'}]:[{key:'energy',label:B('Energy','Enerji'),tone:'energy'},{key:'protein',label:B('Protein','Protein'),tone:'protein'}];
  const title=L(kind==='nitrogen'?B('Estimated nitrogen balance in exactly matched verified collections','Tam eşleşen doğrulanmış toplamalarda yaklaşık azot dengesi'):B('Actual intake as a percentage of the matched physician target','Gerçek alımın eşleşen hekim hedefine oranı'));
  const lines=series.map(s=>{let groups=[],group=[],previous=null;for(const row of rows){const value=kind==='nitrogen'?row.nitrogen:row.percent[s.key];if(typeof value!=='number'){if(group.length)groups.push(group);group=[];previous=null;continue;}if(previous&&Math.abs(row.period.startMs-previous.period.startMs-DAY)>1){if(group.length)groups.push(group);group=[];}group.push({row,value});previous=row;}if(group.length)groups.push(group);return groups.map(g=>`<polyline class="plot-line ${s.tone}" points="${g.map(({row,value})=>`${x(row)},${y(value)}`).join(' ')}"/>${g.map(({row,value})=>`<circle tabindex="0" role="img" aria-label="${esc(row.period.end+' · '+L(s.label)+' '+num(value)+(kind==='nitrogen'?' g N/24h':'%'))}" class="plot-point ${s.tone}" cx="${x(row)}" cy="${y(value)}" r="5"><title>${esc(row.period.end+' · '+L(s.label)+' '+num(value)+(kind==='nitrogen'?' g N/24h':'%'))}</title></circle>`).join('')}`).join('');}).join('');
  const ticks=[min,(min+max)/2,max];const reference=kind==='nitrogen'?0:100;
  return `<figure class="followup-figure"><figcaption>${esc(title)}</figcaption><div class="plot-legend">${series.map(s=>`<span class="${s.tone}">${L(s.label)}</span>`).join('')}</div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>${ticks.map(t=>`<line class="plot-grid" x1="${left}" x2="${width-right}" y1="${y(t)}" y2="${y(t)}"/><text class="plot-axis" x="${left-7}" y="${y(t)+4}" text-anchor="end">${num(t,0)}</text>`).join('')}<line class="plot-reference" x1="${left}" x2="${width-right}" y1="${y(reference)}" y2="${y(reference)}"/>${lines}${rows.filter((r,i)=>rows.length<=8||i===0||i===rows.length-1).map(r=>`<text class="plot-axis" x="${x(r)}" y="${height-16}" text-anchor="middle">${esc(r.period.end.slice(5,10))}</text>`).join('')}</svg><p class="footnote">${L(kind==='nitrogen'?B('Positive retention does not prove muscle anabolism. Missing or mismatched collections are not connected.','Pozitif tutulum kas anabolizmasını kanıtlamaz. Eksik veya eşleşmeyen toplamalar birleştirilmez.'):B('100% denotes the recorded prescription, not a validated biological optimum. Lines stop at missing periods. No catch-up dose is generated.','%100 kaydedilen hekim hedefidir; doğrulanmış biyolojik optimum değildir. Eksik dönemlerde çizgi kesilir. Telafi dozu üretilmez.'))}</p></figure>`;
 }
 function history(){
  const records=getVisits(),selectedIds=records.filter(r=>!excludedIds.has(r.recordId)).map(r=>r.recordId),series=buildDeliverySeries(records,{...scope(),selectedIds}),summary=series.summary;
  $('followupBoard').innerHTML=`<div class="followup-head"><div><span class="eyebrow">${L(B('NUTRITION FOLLOW-UP','BESLENME İZLEMİ'))}</span><h2>${L(B('Prescription, delivery and metabolic observations.','Plan, gerçek alım ve metabolik gözlemler.'))}</h2><p>${L(B('One case, admission, care setting, phase and plan version per comparison.','Her karşılaştırmada tek olgu, yatış, bakım ortamı, faz ve plan sürümü.'))}</p></div><button type="button" id="followupEdit" class="button secondary">${L(B('Record actual intake','Gerçek alımı kaydet'))} →</button></div><p class="followup-scope"><strong>${L(B('Current comparison','Güncel karşılaştırma'))}</strong> · ${signature()}</p>${summary.days?`<div class="followup-kpis">${ratioCard(B('Energy delivered / prescribed','Verilen / hedef enerji'),summary.energyPercent,summary.totalEnergy,summary.targetEnergy,'kcal','energy')}${ratioCard(B('Protein delivered / prescribed','Verilen / hedef protein'),summary.proteinPercent,summary.totalProtein,summary.targetProtein,'g','protein')}<article class="delivery-kpi coverage"><span>${L(B('Verified observation windows','Doğrulanmış gözlem dönemleri'))}</span><strong>${summary.days}<small> × 24h</small></strong><p>${summary.missingDays==null?L(B('Coverage requires aligned periods','Kapsama için dönemler hizalanmalı')):L(B(`${summary.missingDays} missing 24h slots in the retained span`,`${summary.missingDays} adet eksik 24 saatlik dönem`))}</p></article></div><div class="followup-plots">${chart(series.rows)}${chart(series.rows,'nitrogen')}</div><details class="followup-table"><summary>${L(B('Exact observations & signed differences','Kesin gözlemler ve işaretli farklar'))}</summary><div class="table-scroll"><table><thead><tr><th>${L(B('Period end','Dönem sonu'))}</th><th>${L(B('Energy kcal · actual / target','Enerji kcal · gerçek / hedef'))}</th><th>${L(B('Protein g · actual / target','Protein g · gerçek / hedef'))}</th><th>${L(B('Difference · kcal / g','Fark · kcal / g'))}</th><th>NB · g N/24h</th></tr></thead><tbody>${series.rows.map(r=>`<tr><td>${esc(r.period.end)}</td><td>${num(r.actual.energy)} / ${num(r.targets.energy)}</td><td>${num(r.actual.protein)} / ${num(r.targets.protein)}</td><td>${num(r.difference.energy)} / ${num(r.difference.protein)}</td><td>${num(r.nitrogen)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">${L(B('Difference = actual − prescribed. Totals sum only selected valid non-overlapping periods; gaps are not zero intake.','Fark = gerçek − hedef. Toplamlar yalnız seçili, geçerli, çakışmayan dönemleri içerir; boşluk sıfır alım değildir.'))}</p></details>`:`<div class="followup-empty"><span>↗</span><h3>${L(B('Start with one verified day.','Doğrulanmış bir günle başlayın.'))}</h3><p>${L(B('Enter the episode and plan version in the nutrition plan, verify actual 24-hour intake, then save. A formula draft alone cannot create this chart.','Beslenme planında yatış ve plan sürümünü girin, gerçek 24 saatlik alımı doğrulayıp kaydedin. Mama taslağı tek başına bu grafiği oluşturmaz.'))}</p></div>`}${series.excluded.length?`<p class="followup-exclusions">${L(B(`${series.excluded.length} selected records were not pooled. Review scope, verification and overlapping revisions below.`,`${series.excluded.length} seçili kayıt birleştirilmedi. Kapsamı, doğrulamayı ve çakışan revizyonları aşağıda inceleyin.`))}</p>`:''}${getImportedComparisons?.().length?`<p class="footnote">${L(B(`${getImportedComparisons().length} imported comparison snapshots are retained as untrusted provenance. Their selections and conclusions are not activated.`,`${getImportedComparisons().length} aktarılmış karşılaştırma güvenilmeyen kaynak izi olarak saklandı. Seçimleri ve sonuçları etkinleştirilmedi.`))}</p>`:''}<div id="followupIssues">${[...(series.notes||[])].map(v=>`<p class="footnote">${esc(L(v))}</p>`).join('')}</div><details class="followup-selection"><summary>${L(B('Select source records / resolve overlapping revisions','Kaynak kayıtları seç / çakışan revizyonları çöz'))}</summary><p class="footnote">${L(B('Overlapping periods are excluded together. Keep one verified revision by deselecting the others. Reimports do not create new observation days.','Çakışan dönemler birlikte dışlanır. Diğerlerini kaldırarak tek doğrulanmış revizyon seçin. Yeniden aktarım yeni gözlem günü oluşturmaz.'))}</p>${records.length?records.map(r=>{const m=r.delivery?.measures;const issue=series.excluded.find(x=>x.recordId===r.recordId);return `<label class="followup-record"><input type="checkbox" data-followup-record="${esc(r.recordId)}" ${excludedIds.has(r.recordId)?'':'checked'}><span><strong>${esc(r.input.studyId||'—')} · ${esc(m?.episodeId||'—')}</strong><small>${esc(m?.periodStart||'—')} → ${esc(m?.periodEnd||'—')} · ${esc(m?.targetVersion||'—')}</small>${issue?`<small class="record-issue">${issue.reasons.map(v=>esc(L(v))).join(' ')}</small>`:''}</span></label>`;}).join(''):`<p>${L(B('No saved records in this session.','Bu oturumda kayıt yok.'))}</p>`}</details><div class="button-row"><a class="button subtle" href="./FOLLOW-UP-METHODS.md" download>${L(B('Follow-up methods (TR/EN) ↓','İzlem yöntemi (TR/EN) ↓'))}</a>${getInput().demo?`<button type="button" id="followupDemo" class="button subtle">${L(B('Load a synthetic 3-day example','Sentetik 3 günlük izlemi yükle'))}</button>`:''}</div>`;
  $('followupEdit').addEventListener('click',()=>{navigate('plan');$('deliveryForm').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});
  for(const el of document.querySelectorAll('[data-followup-record]'))el.addEventListener('change',()=>{if(el.checked)excludedIds.delete(el.dataset.followupRecord);else excludedIds.add(el.dataset.followupRecord);onDraftChange?.();refresh();});
  $('followupDemo')?.addEventListener('click',()=>onExamples?.());
  return series;
 }
 function reviewPrompts(input,r){const notes=[];if(r.valid){if(r.difference.energy<0||r.difference.protein<0)notes.push(B('Recorded intake is below at least one prescription target. Review chart completeness, interruptions and whether the phase-specific prescription remains appropriate.','Kaydedilen alım en az bir hekim hedefinin altında. Çizelgeyi, kesintileri ve faza özgü hedefin güncel uygunluğunu değerlendirin.'));if(r.difference.energy>0||r.difference.protein>0)notes.push(B('Recorded intake exceeds at least one prescription target. Reconcile all sources and review the current prescription and tolerance with the team.','Kaydedilen alım en az bir hekim hedefinin üstünde. Tüm kaynakları uzlaştırın; güncel planı ve toleransı ekiple değerlendirin.'));if(input.context==='icu'&&input.phase==='early')notes.push(B('Early acute ICU targets may intentionally be progressive or hypocaloric; the percentage is relative to that prescription, not full measured expenditure.','Erken akut YBÜ hedefleri kasıtlı olarak progresif veya hipokalorik olabilir; yüzde tam ölçülen harcamaya değil bu reçeteye göredir.'));if(getResult().blockers.length)notes.push(B('The current formula draft has unresolved safety checks. Recording past delivery does not clear them.','Güncel mama taslağında tamamlanmamış güvenlik kontrolleri var. Geçmiş alımı kaydetmek bunları kaldırmaz.'));}return notes;}
 function refresh(){if(language!==getLocale())fields();const input=getInput(),r=evaluateDelivery(input,measures,getClinicalMeasures?.());
  $('deliveryTargets').innerHTML=`<strong>${L(B('Targets being compared','Karşılaştırılan hedefler'))}</strong><span>${num(input.kcalTarget)} kcal / 24h · ${num(input.proteinTarget)} g / 24h</span><small>${L(contexts[input.context])||'—'} · ${L(phases[input.phase])||'—'} · ${input.clinicianConfirmed?L(B('Physician targets confirmed','Hekim hedefleri doğrulandı')):L(B('Physician target review required','Hekim hedef değerlendirmesi gerekli'))}</small>`;
  $('deliveryResult').innerHTML=`<h3>${L(B('Delivery review','Gerçek alım değerlendirmesi'))}</h3>${r.valid?`${ratioCard(B('Energy delivered / prescribed','Verilen / hedef enerji'),r.percent.energy,r.actual.energy,r.targets.energy,'kcal','energy')}${ratioCard(B('Protein delivered / prescribed','Verilen / hedef protein'),r.percent.protein,r.actual.protein,r.targets.protein,'g','protein')}<p>${L(B('Difference from the prescription','Hekim hedefinden fark'))}: ${num(r.difference.energy)} kcal · ${num(r.difference.protein)} g</p>`:`<ul>${r.errors.map(v=>`<li>${esc(L(v))}</li>`).join('')}</ul>`}${[...reviewPrompts(input,r),...(r.notes||[])].map(v=>`<p class="footnote">${esc(L(v))}</p>`).join('')}${sourceLinks(r.sourceIds)}<p class="footnote">${L(B('Review documentation, interruptions, tolerance, swallowing, fluid/renal changes and the current prescription with the clinical team. No automatic increase, reduction or replacement dose.','Kayıt, kesintiler, tolerans, yutma, sıvı/böbrek değişimi ve güncel planı klinik ekiple değerlendirin. Otomatik artış, azaltma veya telafi dozu yoktur.'))}</p>`;
  const series=history();$('followupReport').innerHTML=`<h3>${L(B('Nutrition follow-up','Beslenme izlemi'))}</h3><p>${signature()}</p><p>${r.valid?L(B(`Actual intake: ${num(r.actual.energy)} kcal, ${num(r.actual.protein)} g protein; ${num(r.percent.energy)}% / ${num(r.percent.protein)}% of the matched targets.`,`Gerçek alım: ${num(r.actual.energy)} kcal, ${num(r.actual.protein)} g protein; eşleşen hedeflerin %${num(r.percent.energy)} / %${num(r.percent.protein)} kadarı.`)):L(B('Current delivery record is incomplete or unverified.','Güncel alım kaydı eksik veya doğrulanmadı.'))}</p><p>${L(B(`${series.summary.days} selected verified 24h windows in the comparison.`,`Karşılaştırmada seçilmiş ${series.summary.days} doğrulanmış 24 saatlik dönem.`))}</p>`;
 }
 return {refresh,getMeasures:()=>structuredClone(measures),snapshot:()=>({version:FOLLOWUP_VERSION,measures:structuredClone(measures),output:evaluateDelivery(getInput(),measures,getClinicalMeasures?.())}),reset(){measures=blank();excludedIds.clear();language='';},invalidate(){measures.confirmed=false;measures.targetsStable=false;language='';},restore(record){measures=restoreDelivery(record?.measures);excludedIds.clear();language='';},setDraft(raw){measures=restoreDelivery(raw);language='';},
 getDraft(){return {measures:structuredClone(measures),selection:{...scope(),selectedIds:getVisits().filter(r=>!excludedIds.has(r.recordId)).map(r=>r.recordId)},excludedIds:[...excludedIds]};},
 restoreDraft(data){
  const raw=data?.measures;measures=restoreDelivery(raw);
  if(raw&&typeof raw==='object'&&!Array.isArray(raw)){
   for(const key of ['episodeId','periodStart','periodEnd','actualEnergy','actualProtein','targetVersion','source']){
    if(!Object.hasOwn(raw,key))continue;const value=raw[key];
    if(value===null||typeof value==='string'&&value.length<=4096||typeof value==='number'&&Number.isFinite(value))measures[key]=value;
    else if(!measures.invalidFields.includes(key))measures.invalidFields.push(key);
   }
  }
  measures.confirmed=false;measures.targetsStable=false;
  const ids=getVisits().map(record=>record.recordId);
  if(Array.isArray(data?.excludedIds))excludedIds=new Set(data.excludedIds.filter(id=>typeof id==='string'&&ids.includes(id)));
  else if(Array.isArray(data?.selection?.selectedIds)){const selected=new Set(data.selection.selectedIds.filter(id=>typeof id==='string'));excludedIds=new Set(ids.filter(id=>!selected.has(id)));}
  else excludedIds=new Set();
  language='';refresh();
 },
 series:()=>{const selection={...scope(),selectedIds:getVisits().filter(r=>!excludedIds.has(r.recordId)).map(r=>r.recordId)};return {version:FOLLOWUP_VERSION,selection,...buildDeliverySeries(getVisits(),selection)};}};
}
